<template>
    <section class="main-content">
        <div class="accordion md-accordion left-filter mt-2" id="accordionEx" role="tablist" aria-multiselectable="true">
            <div class="card">
                <div class="card-header filter-head" role="tab">
                    <h5 class="mb-0">
                        <em class="fa fa-file font-16"></em>NETWORK SHARED DRIVE
                        <span class="expand_all_filters">
                            <span>
                                <a id="NetworkShared" @click="OpenNetworkSharedPopUp" href="javascript:;" data-toggle-tooltip="tooltip" data-original-title="Add Network Shared Credentials">
                                    <i class="fa fa-plus text-white" style="font-size: 18px; margin:13px"></i>
                                </a>
                                <!-- <a id="NetworkSharedBack" @click="BackNetworkListing"  v-if="IsShowBackButton"  href="javascript:;" data-toggle-tooltip="tooltip" data-original-title="Back to network Shared Drive">
                                    <i class="fa fa-arrow-left text-white" style="font-size: 18px; margin:13px"></i>
                                </a> -->
                            </span>
                        </span>
                    </h5>
                </div>
                
            </div>
        </div>
        <div id="main" class="expand show border FullTreeData docstorage_leftaccordian" style="max-height:90vh; overflow-y: auto;">
            <!-- <ul id="FolderFullTree" class="filetree treeview py-1">
                <li id="accordion" class="col-12 float-left p-0 border-bottom expandable" v-for="(item,index) in NetworkSharedFolderOrFile" :key="index"  v-if="item.fileExtension=='folder'">
                    <div class="hitarea expandable-hitarea"></div>
                    <span class="folder" >
                        <a @click="Filelist(item.folderPath,fileUrl,email,password)" class='folderlink myfolder' href='javascript:;'>{{item.folderName}} </a>
                    </span>
                </li>
            </ul> -->
                        <DocCommonTreeView 
                        type="Network"
                        :organizationSpace="organizationSpace"
                        :RecentFolders="RecentPinnedFolderArray"
                        :pinnedFolders="pinnedFolderArray"
                        MySpaceFolders=""
                        :sharedFolders="sharedChildFolder"
                        :routeClass="routeClass"
                        :AdditionalDriveId="AdditionalDriveId"
                        :refCode="refCode"
                        :addClsLeftMenu="addClsLeftMenu"
                       :networkChildFolder="FindalFolderArray"
                        treeId="Networkss"
                       :Filelist="Filelist"
                       @Filelist="Filelist"
                        @Folderlisting="Folderlisting"
                        @SharedFolderIdMoveLeftMenu="SharedFolderIdMoveLeftMenu"
                        :SharedFolderIdMoveLeftMenu="SharedFolderIdMoveLeftMenu"
                        @FolderIdMoveLeftMenu="FolderIdMoveLeftMenu"
                        :checkActionType="checkActionType" :userid="userid" :treeOpenCode="treeOpenCode"
                        :key="RefreshDocCommon"
                         ></DocCommonTreeView>                        
                </div>
        <AddNetworkSharedAccount v-if="openNetworkSharedPopup" @Filelist="Filelist" @ClosePopup="ClosePopup" @items-updated="updateItems"></AddNetworkSharedAccount>
    </section>
</template>
<script>
import DataService from '../../services/DataService';
import AddNetworkSharedAccount from '../../views/UI/Modal/AddNetworkSharedAccount.vue';
import DocCommonTreeView from '../DocCommonTreeView.vue';
export default{
    components:{
        DocCommonTreeView,
        AddNetworkSharedAccount
    },
    async created(){
        var vm=this;
        vm.GetNetworkDriveCredential();
        vm.loggeduserid = vm.GetUserInfo.ID;
    },
    props:{
        networkBreadcrumb:{
            type: String,
            required: false
        },
        FilesListingData:{
            type: Array,
            required: false
        }
    },
    data(){
        return{
            RefreshDocCommon:0,
            NetworkSharedFolderOrFileData:[],
            NetworkSharedFolderOrFile:[],
            openNetworkSharedPopup:false,
            IsShowBackButton:false,
            fileUrl:'',
            email:'',
            password:'',
            FindalFolderArray:[],
            NetworkCredential:[],
            fileExtensions: [
            'dll', 'js', 'txt', 'csv', 'log', 'xml', 'json',
            'pdf', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx',
            'jpg', 'jpeg', 'png', 'gif'
            ],
           
        }
    },
    methods:{
        ClosePopup:function(){
            var vm=this;
            vm.openNetworkSharedPopup=false;
        },
        GetNetworkDriveCredential:async function(){
            var vm=this;
            var params=`type=Network`;
            await DataService.GetAdditionalStorage(params).then((response) => {
                vm.NetworkCredential=JSON.parse(response.data);
                vm.updateItems();
            })
        },
        Folderlisting:function(){
            var vm=this;
            vm.Filelist();
        },
        updateItems(items) {
            var vm=this;
            var params=`folderName=&fileUrl=${vm.NetworkCredential[0].Delta_Link}&userName=${vm.NetworkCredential[0].Email_Id}&password=${vm.NetworkCredential[0].Password}`;
            DataService.NetworkSharedDriveAccess(params).then((response) => {
                  vm.NetworkSharedFolderOrFile= response.data;
                  vm.NetworkSharedFolderOrFile.forEach((value, index) => {
                        var CheckIfExist = vm.FindalFolderArray.filter(function (el) {
                            return el.FOLDER_ID == value.FOLDER_ID;
                        });
                        if (CheckIfExist.length == 0) {
                            if (value.FOLDER_PARENT_ID == null) {
                                let folderId = value.FOLDER_ID
                                let rslt = vm.getChildFolder(folderId, value, vm.NetworkSharedFolderOrFile)
                                vm.FindalFolderArray.push(rslt)
                            }
                        }
                        vm.RefreshDocCommon+=1; 
                  })
                   this.isLoading = false;
                })
                //vm.Filelist();
        },
        getChildFolder: function (folderId, currentItem, data) {

            let ths = this;
            let retrunArray = currentItem
            var childArray = data.filter(function (el, index) {
                return el.FOLDER_PARENT_ID == folderId;
            });
            let finalChildArray = [];
            childArray.forEach((value, index) => {
                let ChildfolderId = value.FOLDER_ID
                var CheckIfExist1 = finalChildArray.filter(function (el) {
                    return el.FOLDER_ID == value.FOLDER_ID;
                });
                if (CheckIfExist1.length == 0) {
                    var CheckIfExist = data.filter(function (el, index) {
                        return el.FOLDER_PARENT_ID == ChildfolderId;
                    });
                    if (CheckIfExist != null && CheckIfExist.length > 0) {
                        let rslt = ths.getChildFolder(ChildfolderId, value, data);
                        finalChildArray.push(rslt);
                    } else {
                        finalChildArray.push(value);
                    }
                }
            });
            retrunArray.chidFolder = finalChildArray;

            return retrunArray
        },
        OpenNetworkSharedPopUp:function(){
           // debugger;
            var vm=this;
            vm.openNetworkSharedPopup=true;
        },
        BackNetworkListing : function(){
            var vm=this;
            vm.IsShowBackButton=true;
            var breadcrumbs="";
            var folderName=null;
            if(vm.networkBreadcrumb!=null){
                let parts = vm.networkBreadcrumb.split('\\\\');
                parts = parts.filter(part => part !== '');
                breadcrumbs = parts.join(' > ').replace(/\\/g, '>');
            }
            var folderLength=breadcrumbs.split(">").length;
            // if(breadcrumbs.split(">")[folderLength-1]==undefined){
            //     folderName="";
            // }
            // else{
            //     if(folderLength-2<=0){
            //         folderName="";
            //     }else{
            //         folderName='\\'+breadcrumbs.split(">")[folderLength-2];
            //     }
            // }
            folderName='\\\\'+breadcrumbs.split(">")[folderLength-1];
            this.Filelist("",vm.fileUrl,vm.UsrName,vm.password);
        
        },
        getFileExtension(fileName) {
            return fileName.slice((fileName.lastIndexOf('.') - 1 >>> 0) + 2); // Extracts file extension
        },
       Filelist:function(foldername,fileUrl,email,password){
        //debugger
        var vm=this;
        vm.IsShowBackButton=true;
        this.networkBreadcrumb=foldername;
            var params=`folderName=${foldername==undefined?"":foldername}&fileUrl=${vm.NetworkCredential[0].Delta_Link}&userName=${vm.NetworkCredential[0].Email_Id}&password=${vm.NetworkCredential[0].Password}`;
            DataService.GetNetworkFileList(params).then((response) => {
                vm.NetworkSharedFolderOrFileData= response.data;
                vm.$emit('array-emitted',vm.NetworkSharedFolderOrFileData,vm.networkBreadcrumb);
            })
        }
     
        
    }
}
</script>

