<template>
 
    <div class="my-popups">
    <loader :is-visible="isLoading"></loader>
        <div class="modal d-block ">
            <div class="modal-dialog modal-dialog-centered ui-draggable">
                <div class="modal-content">
                    <div class="modal-header ui-draggable-handle">
                        <h4 name="header" class="modal-title">
                           {{$t('AddAccount')}}
                        </h4>
                        <button class="close" @click="ClosePopup"><em aria-hidden="true" class="fa fa-times"></em>
                        </button>
                    </div>
                    <div class="modal-body">
                        <Form ref="NetworkSharedDriveAccess">
                        <Field name="File Url" v-slot="{errors}" :rules="{ 'required': true }" >
                                <div class="form-group">
                                    <label for="Url">{{$t('File Url')}}:</label><span class="text-danger">*</span>
                                    <input type="url" placeholder="Enter File Url" v-model="FileUrl" :class="{'form-control':true,'is-invalid':errors[0]}">
                                    <span v-if="errors[0]" name="Description" class="invalid-feedback d-block">{{ errors[0] }}</span>
                                </div>
                               
                            </Field> 

                            <Field name="User Email" v-slot="{errors}" :rules="{ 'required': true }" >
                                <div class="form-group">
                                    <label for="UserName">{{$t('User Email')}}:</label><span class="text-danger">*</span>
                                    <input type="email" placeholder="Enter User Email" v-model="UserName" :class="{'form-control':true,'is-invalid':errors[0]}">
                                    <span v-if="errors[0]" name="Description" class="invalid-feedback d-block">{{ errors[0] }}</span>
                                </div>
                               
                            </Field> 
                                   <Field name="Password" v-slot="{errors}" :rules="{ 'required': true }" >
                                <div class="form-group">
                                    <label for="password">{{$t('Password')}}:</label><span class="text-danger">*</span>
                                    <input type="password" placeholder="Enter Password" v-model="Password" :class="{'form-control':true,'is-invalid':errors[0]}">
                                    <span v-if="errors[0]" name="Description" class="invalid-feedback d-block">{{ errors[0] }}</span>
                                </div>
                               
                            </Field> 

                             
                            <div class="card" style="width: 18rem;">
                                <img class="card-img-top" src="https://talygenv.github.io/Vue-UI-Content/images/networkdrive.png" alt="Card image cap">
                            </div>
                        </Form>
                    </div>
                    <div class="modal-footer text-right">
                        <button title="Search" id="AddFolder"  @click="NetworkSharedDriveAccess()" class="popupgreenbtn btn btn-success formbtn widthhalf pr-2">
                            <em class="fa fa-floppy-o pr-2"></em> {{$t('Save')}}
                        </button>
                        <button title="Cancel" @click="ClosePopup" class="popupredbtn btn btn-danger formbtn widthhalf pr-2">
                            <em aria-hidden="true" class="fa fa-times pr-2"></em> {{$t('Cancel')}}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import DataService from "./../../../services/DataService";
export default {
    data() {
        return {
            FileUrl:'',
            UserName:'',
            Password:'',
            isLoading:false,
            FindalFolderArray:[],
            NetworkSharedFolderOrFile:[]
        };
    },
  methods:{
    ClosePopup:function(){
        var vm=this;
        vm.$emit("ClosePopup");
    },
    NetworkSharedDriveAccess:function(){
        debugger
        var vm=this;
        vm.$refs.NetworkSharedDriveAccess.validate().then(result => {
            if(result){
               var params=`refreshToken=&type=Network&driveName=&emailId=${vm.UserName}&password=${vm.Password}&fileUrl=${vm.FileUrl}`
               DataService.SaveNetworkDriveCredential(params).then((response) => {
                   
               })
            //    this.isLoading = true;
            //     let obj={
            //         fileUrl:vm.FileUrl,
            //         name:vm.UserName,
            //         password:vm.Password
            //     }
            //     vm.$emit('items-updated', obj); 
                vm.$emit("ClosePopup");
                this.isLoading = false;
            }
        })  
        
    }
  }
}
</script>